"""Reusable conversions for Meridian CRM legacy storage conventions."""

from __future__ import annotations

from decimal import Decimal, ROUND_HALF_UP
from typing import Any


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO format."""
    if yyyymmdd is None or yyyymmdd == "" or yyyymmdd == "00000000":
        return None
    return f"{yyyymmdd[0:4]}-{yyyymmdd[4:6]}-{yyyymmdd[6:8]}"


def from_iso(iso: str | None) -> str:
    """Convert an ISO date to the legacy YYYYMMDD representation."""
    if iso is None or iso == "":
        return "00000000"
    return f"{iso[0:4]}{iso[5:7]}{iso[8:10]}"


def yn(char: str | None) -> bool:
    """Convert a legacy Y/N flag to a boolean."""
    return char == "Y"


def to_minor_units(amount: Any, currency: str | None) -> int:
    """Convert a legacy decimal amount to currency minor units using half-up rounding."""
    if amount is None or amount == "":
        value = Decimal("0")
    else:
        value = Decimal(str(amount))

    code = "USD" if currency is None or currency == "" else currency
    exponent = 0 if code == "JPY" else 2
    quantum = Decimal(1).scaleb(-exponent)
    return int((value.quantize(quantum, rounding=ROUND_HALF_UP)) * (10**exponent))
